local GardenToolRackMaker = {}
local PRODUCTS = {
    iron_gardentoolrack = { name = "Železni stojalo za vrtno orodje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni stojalo za vrtno orodje za vrtnarje." },
    bronze_gardentoolrack = { name = "Bronast stojalo za vrtno orodje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast stojalo za vrtno orodje za vrtnarje." },
    silver_gardentoolrack = { name = "Srebrn stojalo za vrtno orodje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn stojalo za vrtno orodje za vrtnarje." },
    gilded_gardentoolrack = { name = "Pozlačen stojalo za vrtno orodje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen stojalo za vrtno orodje za vrtnarje." },
    jewel_set_gardentoolrack = { name = "Draguljast stojalo za vrtno orodje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast stojalo za vrtno orodje za vrtnarje." },
    royal_sovereign_gardentoolrack = { name = "Kraljevski suveren stojalo za vrtno orodje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren stojalo za vrtno orodje z biseri za krono." },
}
local BUILDINGS = {
    gardentoolrack_workshop = { name = "Gardentoolrack delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardentoolrack_house = { name = "Gardentoolrack hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardentoolrack_atelier = { name = "Mojstrski gardentoolrack atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardentoolrack_palace = { name = "Suverena gardentoolrack palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenToolRackMaker.ironStock=14; GardenToolRackMaker.bronzeStock=12; GardenToolRackMaker.woodStock=14; GardenToolRackMaker.leatherStock=8; GardenToolRackMaker.silverStock=8; GardenToolRackMaker.goldStock=6; GardenToolRackMaker.jewelStock=4; GardenToolRackMaker.pearlStock=4
GardenToolRackMaker.productStock = {}; GardenToolRackMaker.buildings = {}; GardenToolRackMaker.maker = nil; GardenToolRackMaker.activeMaking = {}; GardenToolRackMaker.totalProducts = 0; GardenToolRackMaker.dayTimer = 0
function GardenToolRackMaker.init() GardenToolRackMaker.ironStock=14; GardenToolRackMaker.bronzeStock=12; GardenToolRackMaker.woodStock=14; GardenToolRackMaker.leatherStock=8; GardenToolRackMaker.silverStock=8; GardenToolRackMaker.goldStock=6; GardenToolRackMaker.jewelStock=4; GardenToolRackMaker.pearlStock=4; GardenToolRackMaker.productStock={}; GardenToolRackMaker.buildings={}; GardenToolRackMaker.maker=nil; GardenToolRackMaker.activeMaking={}; GardenToolRackMaker.totalProducts=0; GardenToolRackMaker.dayTimer=0; print("[GardenToolRackMaker] Royal Garden Tool Rack Maker System initialized (6 products, 4 buildings)") end
function GardenToolRackMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenToolRackMaker.maker={name=n or ("Stojalnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalnik najet: %s (spretnost: %d)",GardenToolRackMaker.maker.name,s),"success") end; return true end
function GardenToolRackMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenToolRackMaker.build(id) local ok,e=GardenToolRackMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenToolRackMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenToolRackMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenToolRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenToolRackMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenToolRackMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenToolRackMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenToolRackMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenToolRackMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenToolRackMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenToolRackMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenToolRackMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenToolRackMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenToolRackMaker.buildings==0 then return false,"Potrebna stojalna delavnica" end; if not GardenToolRackMaker.maker then return false,"Potreben stojalnik" end; return true end
function GardenToolRackMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenToolRackMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenToolRackMaker.ironStock=GardenToolRackMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenToolRackMaker.bronzeStock=GardenToolRackMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenToolRackMaker.woodStock=GardenToolRackMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenToolRackMaker.leatherStock=GardenToolRackMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenToolRackMaker.silverStock=GardenToolRackMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenToolRackMaker.goldStock=GardenToolRackMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenToolRackMaker.jewelStock=GardenToolRackMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenToolRackMaker.pearlStock=GardenToolRackMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenToolRackMaker.maker then t=math.max(1,t-math.floor(GardenToolRackMaker.maker.skill/13)) end; table.insert(GardenToolRackMaker.activeMaking,{id="gardentoolrack_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenToolRackMaker.completeMaking(m) local q=1.0+(GardenToolRackMaker.getQualityBonus()/100); if GardenToolRackMaker.maker then q=q+(GardenToolRackMaker.maker.skill/140) end; q=math.min(2.5,q); GardenToolRackMaker.productStock[m.productType]=(GardenToolRackMaker.productStock[m.productType] or 0)+m.quantity; GardenToolRackMaker.totalProducts=GardenToolRackMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenToolRackMaker.maker then GardenToolRackMaker.maker.itemsMade=GardenToolRackMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenToolRackMaker.maker.skill=math.min(100,GardenToolRackMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardentoolrack.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenToolRackMaker.update(dt) if not _G.state then return end; GardenToolRackMaker.dayTimer=GardenToolRackMaker.dayTimer+dt; if GardenToolRackMaker.dayTimer>=30 then GardenToolRackMaker.dayTimer=0; for i=#GardenToolRackMaker.activeMaking,1,-1 do local m=GardenToolRackMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenToolRackMaker.completeMaking(m); table.remove(GardenToolRackMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenToolRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenToolRackMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenToolRackMaker.getStats() return {ironStock=GardenToolRackMaker.ironStock,bronzeStock=GardenToolRackMaker.bronzeStock,woodStock=GardenToolRackMaker.woodStock,leatherStock=GardenToolRackMaker.leatherStock,silverStock=GardenToolRackMaker.silverStock,goldStock=GardenToolRackMaker.goldStock,jewelStock=GardenToolRackMaker.jewelStock,pearlStock=GardenToolRackMaker.pearlStock,productStock=GardenToolRackMaker.productStock,numBuildings=#GardenToolRackMaker.buildings,hasMaker=GardenToolRackMaker.maker~=nil,makerName=GardenToolRackMaker.maker and GardenToolRackMaker.maker.name or "—",makerSkill=GardenToolRackMaker.maker and GardenToolRackMaker.maker.skill or 0,activeMaking=#GardenToolRackMaker.activeMaking,totalProducts=GardenToolRackMaker.totalProducts} end
return GardenToolRackMaker
